"""Embedded interface for the local Parison Workbench."""

PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width">
<title>Parison Workbench</title>
<style>
:root{font:15px/1.5 system-ui,sans-serif;color:#172033;background:#f4f6f9}
*{box-sizing:border-box}body{margin:0}.shell{min-height:100vh;display:grid;grid-template-columns:15rem 1fr}
aside{background:#101828;color:#d0d5dd;padding:1.75rem 1rem;display:flex;flex-direction:column;gap:2rem}
.brand{padding:0 .75rem}.brand strong{display:block;color:#fff;font-size:1.15rem}.brand span{font-size:.8rem;color:#98a2b3}
nav{display:grid;gap:.35rem}.nav-item{display:flex;justify-content:space-between;align-items:center;width:100%;padding:.65rem .75rem;border:0;border-radius:.45rem;background:transparent;color:#d0d5dd;text-align:left;font-weight:400}
.nav-item:hover{background:#1d2939}.nav-item.active{background:#344054;color:#fff;font-weight:650}.nav-item[aria-disabled=true]{color:#667085;cursor:default}.nav-item[aria-disabled=true]:hover{background:transparent}
.soon{font-size:.68rem;text-transform:uppercase;letter-spacing:.05em}
.local{margin-top:auto;padding:.75rem;border:1px solid #344054;border-radius:.5rem;font-size:.8rem}.local strong{display:block;color:#ecfdf3}.dot{display:inline-block;width:.5rem;height:.5rem;border-radius:50%;background:#32d583;margin-right:.4rem}
.workspace{min-width:0}.topbar{height:4.5rem;background:#fff;border-bottom:1px solid #e4e7ec;display:flex;align-items:center;justify-content:space-between;padding:0 2rem}
.topbar p{margin:0;color:#667085}.session{font-size:.8rem;color:#027a48;background:#ecfdf3;border:1px solid #abefc6;border-radius:999px;padding:.25rem .65rem}
main{max-width:70rem;margin:0 auto;padding:3rem 2rem 5rem}.eyebrow{margin:0 0 .4rem;color:#475467;font-size:.8rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
h1{font-size:2.25rem;line-height:1.15;margin:.2rem 0 .75rem;letter-spacing:-.03em}h2{margin:0 0 .35rem}.lede{max-width:46rem;color:#667085;font-size:1.05rem;margin:0 0 2rem}
.card{background:#fff;border:1px solid #d0d5dd;border-radius:.75rem;box-shadow:0 1px 2px #1018280d}.open-card{padding:1.4rem}
form{display:grid;grid-template-columns:1fr auto;gap:.75rem;align-items:end}label{display:grid;gap:.4rem;font-weight:650}label span{font-weight:400;color:#667085;font-size:.82rem}.actions{display:flex;gap:.5rem}
input,button,textarea{font:inherit}input{width:100%;padding:.72rem .8rem;border:1px solid #98a2b3;border-radius:.45rem;background:#fff;color:#101828}input:focus,textarea:focus{outline:3px solid #84adff55;border-color:#175cd3}
button{border:1px solid #175cd3;border-radius:.45rem;padding:.72rem 1rem;background:#175cd3;color:#fff;font-weight:650;cursor:pointer}button:hover{background:#1849a9}button:focus-visible{outline:3px solid #84adff}
button:disabled{cursor:wait;opacity:.6}
.secondary{background:#fff;color:#344054;border-color:#98a2b3}.secondary:hover{background:#f2f4f7}.clear{padding:.45rem .7rem}
.status{margin:1rem 0 0;color:#475467}.empty{margin-top:1.5rem;padding:3.5rem 2rem;text-align:center}.mark{width:3rem;height:3rem;margin:0 auto 1rem;border-radius:50%;display:grid;place-items:center;background:#eef4ff;color:#175cd3;font-size:1.25rem;font-weight:800}
.empty p{max-width:34rem;margin:.3rem auto;color:#667085}.evidence{margin-top:1.5rem;overflow:hidden}.evidence header{padding:1.25rem 1.4rem;border-bottom:1px solid #e4e7ec;display:flex;justify-content:space-between;align-items:center}
.outcome{font-size:.78rem;font-weight:750;border-radius:999px;padding:.25rem .6rem}.outcome.pass{color:#027a48;background:#ecfdf3}.outcome.other{color:#b42318;background:#fef3f2}
table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd3da;padding:.65rem .85rem;text-align:left;vertical-align:top;border-left:0;border-right:0}th{width:34%;background:#f8fafc;color:#344054}code{overflow-wrap:anywhere;color:#344054}
.boundary{margin-top:1.5rem;padding:1rem 1.2rem;border-left:3px solid #84adff;background:#eef4ff;color:#344054}.boundary strong{display:block;margin-bottom:.2rem}
.editor{margin-top:1.5rem;overflow:hidden}.editor header{padding:1.25rem 1.4rem;border-bottom:1px solid #e4e7ec;display:flex;justify-content:space-between;align-items:center}.meta{display:flex;flex-wrap:wrap;gap:.5rem;padding:1rem 1.4rem;background:#f8fafc;border-bottom:1px solid #e4e7ec}.meta span{padding:.2rem .55rem;border:1px solid #d0d5dd;border-radius:999px;background:#fff;font-size:.78rem}.digest{overflow-wrap:anywhere}.editor-body{padding:1.4rem}.editor-body label{display:block;margin-bottom:.45rem}.editor textarea{display:block;width:100%;min-height:25rem;resize:vertical;padding:.85rem;border:1px solid #98a2b3;border-radius:.45rem;background:#101828;color:#f2f4f7;font:13px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;tab-size:2}.editor-footer{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-top:1rem}.editor-footer .status{margin:0}.commands{margin-top:1.5rem;padding:1.2rem 1.4rem}.commands pre{overflow:auto;margin:.75rem 0 0;padding:1rem;border-radius:.45rem;background:#101828;color:#f2f4f7}.commands code{color:inherit}
@media(max-width:760px){.shell{grid-template-columns:1fr}aside{padding:1rem;gap:1rem}nav{grid-template-columns:repeat(3,1fr)}.nav-item{padding:.5rem;font-size:.8rem}.soon{display:none}.local{display:none}.topbar{padding:0 1rem}main{padding:2rem 1rem}form{grid-template-columns:1fr}}
</style>
</head>
<body><div class="shell">
<aside><div class="brand"><strong>Parison</strong><span>Verification workbench</span></div>
<nav aria-label="Workbench activities">
<button class="nav-item" data-view="plans" type="button">Plans</button>
<span class="nav-item" aria-disabled="true">Run <span class="soon">Planned</span></span>
<button class="nav-item active" data-view="results" type="button" aria-current="page">Results</button>
<span class="nav-item" aria-disabled="true">History <span class="soon">Planned</span></span>
<span class="nav-item" aria-disabled="true">Investigate <span class="soon">Planned</span></span>
<span class="nav-item" aria-disabled="true">Compare <span class="soon">Planned</span></span>
</nav>
<div class="local"><strong><span class="dot"></span>Local only</strong>No network, credentials, or remote execution.</div></aside>
<div class="workspace"><header class="topbar"><p>Current workspace</p><span id="session" class="session" role="status">Connecting...</span></header>
<main><section id="plans-view" hidden><p class="eyebrow">Explicit policy</p><h1>Plans</h1>
<p class="lede">Open a CLI-native recipe to review the exact JSON and its effective policy identity before execution.</p>
<section class="card open-card"><form id="open-plan"><label for="recipe">Recipe file <span>Choose a JSON file or enter its path relative to this workspace.</span><input id="recipe" required placeholder="recipes/example.json" autocomplete="off"></label><div class="actions"><button id="choose-recipe" class="secondary" type="button">Choose file...</button><button>Validate and open</button></div></form><p id="plan-open-status" class="status" role="status">Ready for a local recipe.</p></section>
<section id="plan-empty" class="card empty"><div class="mark">{ }</div><h2>No plan open</h2><p>Open an existing Parison recipe. The Python engine validates it before the editor displays its exact source.</p></section>
<section id="plan-editor" class="card editor" hidden><header><div><p class="eyebrow">Verification plan</p><h2>CLI-native JSON</h2></div><button id="clear-plan" class="secondary clear" type="button">Clear plan</button></header><div class="meta"><span id="recipe-version"></span><span id="comparison-mode"></span><span class="digest">Policy <code id="policy-sha"></code></span></div><div class="editor-body"><label for="plan-source">Recipe source</label><textarea id="plan-source" spellcheck="false"></textarea><div class="editor-footer"><p id="plan-status" class="status" role="status"></p><div class="actions"><button id="validate-plan" class="secondary" type="button">Validate changes</button><button id="download-plan" type="button">Download unapproved draft</button></div></div></div></section>
<section id="commands" class="card commands" hidden><h2>Equivalent CLI</h2><pre><code>parison validate-recipe plan.json
parison compare --recipe plan.json --baseline BASELINE --candidate CANDIDATE --output RUN_DIRECTORY</code></pre></section>
<aside class="boundary"><strong>Policy review required</strong>This editor never approves keys, tolerances, scope, exclusions, sensitivity, or repairs. A downloaded draft remains unapproved until you review and validate it.</aside></section>
<section id="results-view"><p class="eyebrow">Verified evidence</p><h1 id="heading">Results</h1>
<p class="lede">Open a published Parison bundle to verify its integrity and inspect a summary-safe result.</p>
<section class="card open-card"><form id="open"><label for="bundle">Bundle folder <span>Choose a folder or enter its path relative to this workspace.</span><input id="bundle" required placeholder="runs/example" autocomplete="off"></label><div class="actions"><button id="choose" class="secondary" type="button">Choose folder...</button><button>Verify and open</button></div></form><p id="status" class="status" role="status">Ready for a local bundle.</p></section>
<section id="empty" class="card empty"><div class="mark">P</div><h2>No result open</h2><p>Choose the bundle folder—not an individual <code>result.json</code> file. Parison verifies every manifest-covered artifact before showing evidence.</p></section>
<section id="result" class="card evidence" hidden><header><div><p class="eyebrow">Verification result</p><h2>Summary-safe evidence</h2></div><div class="actions"><span id="outcome" class="outcome"></span><button id="clear" class="secondary clear" type="button">Clear result</button></div></header><table><tbody id="evidence"></tbody></table></section>
<aside class="boundary"><strong>What PASS means</strong>Agreement under the displayed policy—not extraction truth, approval, or cutover authorization. This view excludes source paths, keys, values, and discrepancy samples.</aside>
</section></main></div></div>
<script>
const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);
const session=document.getElementById('session'),status=document.getElementById('status'),body=document.getElementById('evidence'),heading=document.getElementById('heading'),result=document.getElementById('result'),empty=document.getElementById('empty'),outcome=document.getElementById('outcome');
const post=(path,data)=>fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Parison-Session':token},body:JSON.stringify(data)});
post('/api/session',{}).then(r=>r.ok?r.json():Promise.reject()).then(()=>session.textContent='Local workspace ready').catch(()=>{session.textContent='Session rejected';session.style.color='#b42318'});
document.querySelectorAll('[data-view]').forEach(item=>item.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(other=>{other.classList.toggle('active',other===item);other.toggleAttribute('aria-current',other===item)});document.getElementById('plans-view').hidden=item.dataset.view!=='plans';document.getElementById('results-view').hidden=item.dataset.view!=='results'}));
const form=document.getElementById('open'),bundle=document.getElementById('bundle'),choose=document.getElementById('choose');
choose.addEventListener('click',async()=>{choose.disabled=true;status.textContent='Choose a bundle folder inside this workspace...';try{const response=await post('/api/choose-bundle',{});if(response.status===204){status.textContent='Folder selection cancelled.';return}if(!response.ok){status.textContent='Folder could not be selected. Choose a folder inside this workspace or enter its relative path.';return}bundle.value=(await response.json()).bundle;form.requestSubmit()}catch(error){status.textContent='Folder picker unavailable. Enter a workspace-relative path instead.'}finally{choose.disabled=false}});
form.addEventListener('submit',async event=>{event.preventDefault();status.textContent='Verifying bundle...';body.replaceChildren();
const response=await post('/api/evidence',{bundle:bundle.value});if(!response.ok){status.textContent='Bundle could not be verified. Select the bundle folder within this workspace.';result.hidden=true;empty.hidden=false;return}
const evidence=await response.json();const name=evidence.outcome||'Result';heading.textContent=name;outcome.textContent=name;outcome.className='outcome '+(name==='PASS'?'pass':'other');
const rows=(value,prefix='')=>{if(value&&typeof value==='object'&&!Array.isArray(value)){Object.keys(value).sort().forEach(key=>rows(value[key],prefix?prefix+'.'+key:key));return}const row=document.createElement('tr'),label=document.createElement('th'),cell=document.createElement('td'),code=document.createElement('code');label.scope='row';label.textContent=prefix;code.textContent=Array.isArray(value)?value.join(', '):JSON.stringify(value);cell.append(code);row.append(label,cell);body.append(row)};
rows(evidence);empty.hidden=true;result.hidden=false;status.textContent='Verified bundle integrity. Showing summary-safe evidence.'});
document.getElementById('clear').addEventListener('click',()=>{body.replaceChildren();result.hidden=true;empty.hidden=false;heading.textContent='Results';heading.style.color='';outcome.textContent='';form.reset();status.textContent='Result cleared. Ready for a local bundle.';bundle.focus()});
const planForm=document.getElementById('open-plan'),recipe=document.getElementById('recipe'),chooseRecipe=document.getElementById('choose-recipe'),planOpenStatus=document.getElementById('plan-open-status'),planEmpty=document.getElementById('plan-empty'),planEditor=document.getElementById('plan-editor'),commands=document.getElementById('commands'),planSource=document.getElementById('plan-source'),planStatus=document.getElementById('plan-status'),validatePlan=document.getElementById('validate-plan'),downloadPlan=document.getElementById('download-plan'),policySha=document.getElementById('policy-sha');
chooseRecipe.addEventListener('click',async()=>{chooseRecipe.disabled=true;planOpenStatus.textContent='Choose a recipe file inside this workspace...';try{const response=await post('/api/choose-recipe',{});if(response.status===204){planOpenStatus.textContent='File selection cancelled.';return}if(!response.ok){planOpenStatus.textContent='File could not be selected. Choose a file inside this workspace or enter its relative path.';return}recipe.value=(await response.json()).recipe;planForm.requestSubmit()}catch(error){planOpenStatus.textContent='File picker unavailable. Enter a workspace-relative path instead.'}finally{chooseRecipe.disabled=false}});
const showPolicy=plan=>{document.getElementById('recipe-version').textContent='Recipe v'+plan.recipe_version;document.getElementById('comparison-mode').textContent=plan.comparison_mode;policySha.textContent=plan.policy_sha256};
planForm.addEventListener('submit',async event=>{event.preventDefault();planOpenStatus.textContent='Validating recipe...';const response=await post('/api/plan',{recipe:recipe.value});if(!response.ok){planOpenStatus.textContent='Recipe could not be validated. Select a Parison recipe within this workspace.';planEditor.hidden=true;commands.hidden=true;planEmpty.hidden=false;return}const plan=await response.json();planSource.value=plan.source;showPolicy(plan);downloadPlan.disabled=false;planStatus.textContent='Loaded plan passed authoritative Python validation.';planEmpty.hidden=true;planEditor.hidden=false;commands.hidden=false;planOpenStatus.textContent='Validated recipe and computed its effective policy identity.'});
planSource.addEventListener('input',()=>{downloadPlan.disabled=true;policySha.textContent='Revalidate to compute';try{const value=JSON.parse(planSource.value);if(!value||Array.isArray(value)||typeof value!=='object')throw Error('top level must be an object');planStatus.textContent='Valid JSON; authoritative Parison validation is required before download.'}catch(error){planStatus.textContent='Invalid JSON: '+error.message}});
validatePlan.addEventListener('click',async()=>{const source=planSource.value;validatePlan.disabled=true;planStatus.textContent='Validating changes with Parison...';try{const response=await post('/api/validate-plan',{source});if(planSource.value!==source){planStatus.textContent='Plan changed during validation. Validate the current text again.';return}if(!response.ok){downloadPlan.disabled=true;policySha.textContent='Validation failed';planStatus.textContent='Plan failed authoritative Parison validation.';return}showPolicy(await response.json());downloadPlan.disabled=false;planStatus.textContent='Changes passed authoritative Python validation. Draft download is enabled.'}catch(error){planStatus.textContent='Plan could not be validated.'}finally{validatePlan.disabled=false}});
downloadPlan.addEventListener('click',()=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([planSource.value.endsWith('\\n')?planSource.value:planSource.value+'\\n'],{type:'application/json'}));link.download='plan.json';link.click();URL.revokeObjectURL(link.href);planStatus.textContent='Downloaded validated, unapproved draft.'});
document.getElementById('clear-plan').addEventListener('click',()=>{planForm.reset();planSource.value='';downloadPlan.disabled=true;planEditor.hidden=true;commands.hidden=true;planEmpty.hidden=false;planOpenStatus.textContent='Plan cleared. Ready for a local recipe.';recipe.focus()});
</script></body></html>""".encode()
